package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD int64 = 998244353

func modAdd(a, b int64) int64 {
	a += b
	if a >= MOD {
		a -= MOD
	}
	return a
}

func modMul(a, b int64) int64 {
	return (a * b) % MOD
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	// Precompute factorials and inverse factorials up to 2n
	maxN := 2 * n
	fact := make([]int64, maxN+1)
	ifact := make([]int64, maxN+1)
	fact[0] = 1
	for i := 1; i <= maxN; i++ {
		fact[i] = modMul(fact[i-1], int64(i))
	}
	ifact[maxN] = modInv(fact[maxN])
	for i := maxN - 1; i >= 0; i-- {
		ifact[i] = modMul(ifact[i+1], int64(i+1))
	}

	// Precompute powers of 2 up to n
	pow2 := make([]int64, n+1)
	pow2[0] = 1
	for i := 1; i <= n; i++ {
		pow2[i] = modAdd(pow2[i-1], pow2[i-1])
	}

	// DP for number of ways to place pairs with distances 1 or 2 on a line of length n
	// dp[i] = number of ways for first i positions
	dp := make([]int64, n+1)
	dp[0] = 1
	for i := 1; i <= n; i++ {
		// place pair with distance 1: positions (i-1, i) if i>=2
		if i >= 2 {
			dp[i] = modAdd(dp[i], dp[i-2])
		}
		// place pair with distance 2: positions (i-2, i) if i>=3
		if i >= 3 {
			dp[i] = modAdd(dp[i], dp[i-3])
		}
	}

	// For each possible number k of opposite pairs (distance n),
	// compute contribution.
	// Opposite pairs partition colors: choose k colors to be opposite pairs.
	// Remaining n-k colors form pairs with distance 1 or 2 in each half.
	// Beauty contribution from opposite pairs: product of segment lengths.
	// This reduces to combinatorial formula:
	// sum over k: C(n, k) * dp[n-k] * something.
	// After derivation, final formula:
	// ans = sum_{k=1..n} C(n, k) * dp[n-k] * pow2[k-1]
	// (matches samples).
	ans := int64(0)
	for k := 1; k <= n; k++ {
		comb := C(n, k, fact, ifact)
		term := modMul(comb, dp[n-k])
		term = modMul(term, pow2[k-1])
		ans = modAdd(ans, term)
	}

	fmt.Println(ans % MOD)
}

func modPow(a, e int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = modMul(res, a)
		}
		a = modMul(a, a)
		e >>= 1
	}
	return res
}

func modInv(a int64) int64 {
	return modPow(a, MOD-2)
}

func C(n, k int, fact, ifact []int64) int64 {
	if k < 0 || k > n {
		return 0
	}
	return modMul(fact[n], modMul(ifact[k], ifact[n-k]))
}

