const MOD int64 = 998244353

func modAdd(a, b int64) int64 {
	res := a + b
	if res >= MOD {
		res -= MOD
	}
	return res
}

func modMul(a, b int64) int64 {
	return (a * b) % MOD
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)

	// Precompute factorials and inverse factorials up to 2n
	maxN := 2 * n
	fact := make([]int64, maxN+1)
	ifact := make([]int64, maxN+1)
	fact[0] = 1
	for i := 1; i <= maxN; i++ {
		fact[i] = modMul(fact[i-1], int64(i))
	}
	ifact[maxN] = modPow(fact[maxN], MOD-2)
	for i := maxN; i > 0; i-- {
		ifact[i-1] = modMul(ifact[i], int64(i))
	}

	// DP for number of valid matchings and sum of beauties
	// dp[i] = number of valid matchings on i positions
	// sumB[i] = sum of beauties over all matchings on i positions
	dp := make([]int64, n+1)
	sumB := make([]int64, n+1)
	dp[0] = 1
	sumB[0] = 0

	for i := 1; i <= n; i++ {
		// We consider placing a pair at distance 1, 2, or n (but n only when i == n)
		var ways int64
		var beautySum int64

		// distance 1 (adjacent)
		if i >= 1 {
			ways = modAdd(ways, dp[i-1])
			beautySum = modAdd(beautySum, sumB[i-1])
		}
		// distance 2
		if i >= 2 {
			ways = modAdd(ways, dp[i-2])
			beautySum = modAdd(beautySum, sumB[i-2])
		}
		// distance n (only once when i == n)
		if i == n {
			ways = modAdd(ways, dp[0])
			// removing opposite pairs splits into segments; beauty contribution is product of segment lengths
			// For the full circle, this is simply (n-2)!! (number of ways to pair remaining)
			// But we already count in dp; here we just add dp[0] * 0 since beauty is 0 when no opposite pair
			// So no extra beauty contribution here.
		}

		dp[i] = ways
		sumB[i] = beautySum
	}

	// Now we need to account for labeling of colors and positions.
	// Each matching corresponds to assigning colors to pairs.
	// Number of ways to assign n colors to n pairs: n! (each color used exactly twice).
	// Also, positions are fixed; we don't divide by rotations.
	ans := modMul(sumB[n], fact[n])

	fmt.Println(ans % MOD)
}

